// Topology document loading and validation, plus display helpers.
//
// Topology documents come from the Rust projection (`araiguma topology`).
// In mock mode they come from the committed golden fixtures, which are
// generated BY the Rust projection — the UI never invents topology.

import workstationTopology from '../../../../fixtures/topology/workstation.json';
import incompleteTopology from '../../../../fixtures/topology/incomplete-observations.json';
import serverTunnelTopology from '../../../../fixtures/topology/server-tunnel.json';
import dummyVirtualTopology from '../../../../fixtures/topology/dummy-virtual.json';
import emptyTopology from '../../../../fixtures/topology/empty.json';
import type {
  NodeId,
  TopologyDocument,
  TopologyEdgeKind,
  TopologyNode,
} from '../types';
import { isMacObservation } from './format';

export interface TopologyFixture {
  name: string;
  description: string;
  document: TopologyDocument;
}

const rawGoldens: Record<string, { description: string; json: unknown }> = {
  workstation: {
    description: 'Synthetic laptop: ethernet + Wi-Fi + WireGuard + bridge + dummy',
    json: workstationTopology,
  },
  'incomplete-observations': {
    description: 'netlink unavailable; sysfs/procfs-only observation',
    json: incompleteTopology,
  },
  'server-tunnel': {
    description: 'server with tunnel default (no gateway) and ethernet default',
    json: serverTunnelTopology,
  },
  'dummy-virtual': {
    description: 'bridge port, vlan parent, veth pair, dummy',
    json: dummyVirtualTopology,
  },
  empty: {
    description: 'no observations at all',
    json: emptyTopology,
  },
};

export const topologyGoldens: TopologyFixture[] = Object.entries(rawGoldens).map(
  ([name, { description, json }]) => ({
    name,
    description,
    document: parseTopology(json),
  }),
);

export function defaultTopology(): TopologyDocument {
  return topologyGoldens[0].document;
}

// Validate and load an unknown JSON value as a TopologyDocument.
export function parseTopology(input: unknown): TopologyDocument {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new Error('invalid topology document: expected an object');
  }
  const doc = input as Record<string, unknown>;
  const schema = doc.schemaVersion;
  if (schema !== 1 && schema !== 2) {
    throw new Error(
      `invalid topology document: unsupported schemaVersion ${String(schema)} (expected 1 or 2; this build writes v2)`,
    );
  }
  if (!Array.isArray(doc.nodes) || !Array.isArray(doc.edges)) {
    throw new Error('invalid topology document: nodes and edges must be arrays');
  }
  for (const node of doc.nodes as Record<string, unknown>[]) {
    if (typeof node.label !== 'string' || node.label.length === 0) {
      throw new Error('invalid topology document: every node needs a label');
    }
    const id = node.id as Record<string, unknown> | undefined;
    if (!id || (!('interface' in id) && !('gateway' in id))) {
      throw new Error(`invalid topology document: node ${String(node.label)} has no id`);
    }
    if (node.nodeKind !== 'interface' && node.nodeKind !== 'gateway') {
      throw new Error(`invalid topology document: node ${String(node.label)} has an unknown kind`);
    }
    // MAC observation in node details follows the same v2 rule as
    // snapshots: address string or sentinels, never null.
    const detail = node.detail as Record<string, unknown> | undefined;
    if (detail !== undefined) {
      if (detail.macAddress === null || detail.macAddress === undefined) {
        throw new Error(
          `invalid topology document: node ${String(node.label)} detail.macAddress must not be null/absent — v1 null was ambiguous between "observed no hardware address" and "not observed"`,
        );
      }
      if (!isMacObservation(detail.macAddress)) {
        throw new Error(
          `invalid topology document: node ${String(node.label)} detail.macAddress is not a hardware address or the sentinels 'absent'/'notObserved'`,
        );
      }
    }
  }
  return doc as unknown as TopologyDocument;
}

// Stable string key for a NodeId (used for selection and cytoscape ids).
export function nodeIdKey(id: NodeId): string {
  return 'interface' in id
    ? `if:${id.interface.ifindex}`
    : `gw:${id.gateway.address}`;
}

export function nodeKindLabel(node: TopologyNode): string {
  if (node.nodeKind === 'gateway') {
    return 'Gateway (routing fact)';
  }
  return node.interfaceKind ? interfaceKindLabel(node.interfaceKind) : 'Interface';
}

function interfaceKindLabel(kind: string): string {
  const labels: Record<string, string> = {
    loopback: 'Loopback',
    ethernet: 'Ethernet',
    wireless: 'Wi-Fi',
    bridge: 'Bridge',
    bond: 'Bond',
    dummy: 'Dummy',
    wireguard: 'WireGuard',
    tunnel: 'Tunnel',
    veth: 'veth endpoint',
    vlan: 'VLAN',
    virtual: 'Virtual (unclassified)',
    other: 'Other',
  };
  return labels[kind] ?? 'Other';
}

export function edgeKindLabel(kind: TopologyEdgeKind): string {
  switch (kind) {
    case 'bridgeMember':
      // Only where the master's own kind was observed as a bridge.
      return 'bridge port';
    case 'bondMember':
      // Only where the master's own kind was observed as a bond.
      return 'bond member';
    case 'masterMember':
      // The kernel named the master, but its type was not established —
      // never assumed to be a bridge.
      return 'port of master (type not established)';
    case 'linkParent':
      return 'parent link';
    case 'gatewayRoute':
      return 'route via gateway';
    case 'gatewayInferred':
      return 'gateway (inferred)';
  }
}

export function evidenceLabel(evidence: TopologyDocument['edges'][number]['evidence']): string {
  if ('observed' in evidence) {
    return `observed (${evidence.observed.source})`;
  }
  return `inferred — ${evidence.inferred.reason}`;
}

// The nodes a route refers to (for linkage highlighting): its output
// interface and its gateway, when present in the document.
export function routeHighlightTargets(
  route: { outputInterface: number | null; gateway: string | null },
  document: TopologyDocument,
): NodeId[] {
  const targets: NodeId[] = [];
  if (route.outputInterface !== null) {
    const exists = document.nodes.some(
      (n) => 'interface' in n.id && n.id.interface.ifindex === route.outputInterface,
    );
    if (exists) {
      targets.push({ interface: { ifindex: route.outputInterface } });
    }
  }
  if (route.gateway !== null) {
    const exists = document.nodes.some(
      (n) => 'gateway' in n.id && n.id.gateway.address === route.gateway,
    );
    if (exists) {
      targets.push({ gateway: { address: route.gateway } });
    }
  }
  return targets;
}
